package dev.servicelog.photo;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.regex.Pattern;

// Image files in a folder on disk (a Docker volume in production). Kept behind this class
// so moving to object storage (e.g. S3) later only changes this file.
@Component
public class PhotoStorage {

    // Keys are generated by PhotoService; anything else could be a path trick
    private static final Pattern SAFE_KEY = Pattern.compile("[a-f0-9-]{36}(-thumb)?\\.jpg");

    private final Path dir;

    public PhotoStorage(@Value("${servicelog.photos.dir}") String dir) {
        this.dir = Path.of(dir).toAbsolutePath().normalize();
        try {
            Files.createDirectories(this.dir);
        } catch (IOException e) {
            throw new UncheckedIOException("Can't create the photo folder " + this.dir, e);
        }
    }

    public void save(String key, byte[] bytes) {
        try {
            Files.write(path(key), bytes);
        } catch (IOException e) {
            throw new UncheckedIOException("Couldn't save photo " + key, e);
        }
    }

    public byte[] load(String key) {
        try {
            return Files.readAllBytes(path(key));
        } catch (IOException e) {
            throw new UncheckedIOException("Couldn't read photo " + key, e);
        }
    }

    public void delete(String key) {
        try {
            Files.deleteIfExists(path(key));
        } catch (IOException e) {
            throw new UncheckedIOException("Couldn't delete photo " + key, e);
        }
    }

    public boolean exists(String key) {
        return Files.exists(path(key));
    }

    private Path path(String key) {
        if (!SAFE_KEY.matcher(key).matches()) {
            throw new IllegalArgumentException("Not a photo key: " + key);
        }
        return dir.resolve(key);
    }
}
